from concurrent.futures import ThreadPoolExecutor, ProcessPoolExecutor
import requests

def fetch_status(url):
    return url, requests.get(url, timeout=10).status_code

def is_prime(n):
    if n < 2:
        return False
    return all(n % i for i in range(2, int(n ** 0.5) + 1))

if __name__ == "__main__":
    urls = ["https://example.com", "https://httpbin.org/get"]
    with ThreadPoolExecutor(max_workers=5) as pool:     # I/O bound
        for url, status in pool.map(fetch_status, urls):
            print(status, url)

    numbers = range(1_000_000, 1_000_050)
    with ProcessPoolExecutor() as pool:                  # CPU bound
        flags = list(pool.map(is_prime, numbers))
    print(sum(flags), "primes found")

class Plain:
    def __init__(self, x, y):
        self.x, self.y = x, y

class Slotted:
    __slots__ = ("x", "y")
    def __init__(self, x, y):
        self.x, self.y = x, y

p, s = Plain(1, 2), Slotted(1, 2)
print(hasattr(p, "__dict__"), hasattr(s, "__dict__"))
try:
    s.z = 3
except AttributeError:
    print("slotted objects reject new attributes")

squares = (n * n for n in range(10 ** 8))   # nothing computed yet
print(next(squares), next(squares), next(squares))
print(sum(n * n for n in range(1000)))

import timeit
fast = timeit.timeit("5000 in s", setup="s = set(range(10000))", number=2000)
slow = timeit.timeit("5000 in l", setup="l = list(range(10000))", number=2000)
print("set lookup faster than list:", fast < slow)

import pytest
from unittest.mock import patch

# app.py
import requests

def get_title(url):
    return requests.get(url, timeout=10).json()["title"]

def divide(a, b):
    return a / b

# test_app.py
@pytest.fixture
def numbers():
    return [1, 2, 3]

def test_sum(numbers):
    assert sum(numbers) == 6

@pytest.mark.parametrize("a,b,expected", [(6, 3, 2), (5, 2, 2.5), (0, 4, 0)])
def test_divide(a, b, expected):
    assert divide(a, b) == expected

def test_divide_by_zero():
    with pytest.raises(ZeroDivisionError):
        divide(1, 0)

def test_get_title():
    with patch("app.requests.get") as fake_get:
        fake_get.return_value.json.return_value = {"title": "Hello"}
        assert get_title("http://x.test") == "Hello"
